static Bounds Bounds(GameObject go){var rs=go.GetComponentsInChildren<Renderer>();var b=rs[0].bounds;foreach(var r in rs)b.Encapsulate(r.bounds);return b;}
static void Build(){var scene=EditorSceneManager.OpenScene(A+"PondFloraSoftGrass.unity");UnityEngine.Object.DestroyImmediate(GameObject.Find("Pond edge low flora experiment"));
var terrain=UnityEngine.Object.FindFirstObjectByType<Terrain>(FindObjectsInactive.Include);var root=new GameObject("Pond edge low flora experiment");var names=new[]{"Cord Leaf A1","Silk Vein A1","Rift Weed A2","Alstilbe","Fleeting Sage B2"};var sources=names.Select(n=>AssetDatabase.LoadAssetAtPath<GameObject>("Assets/(PBR) Low-Grow Flora/Prefabs/Med Res/"+n+".prefab")).ToArray();var mats=new Dictionary<Material,Material>();var rng=new System.Random(721);int count=0;var report=new List<string>();
foreach(var s in sources){var temp=UnityEngine.Object.Instantiate(s);report.Add(s.name+" source dimensions "+Bounds(temp).size);UnityEngine.Object.DestroyImmediate(temp);}
for(int j=0;j<36;j++){float angle=j*6.28318f/36+.06f*Mathf.Sin(j*2.17f);for(int k=0;k<35+(int)(angle*17)%40;k++){float a=angle+((float)rng.NextDouble()-.5f)*.24f;var dir=new Vector3(Mathf.Cos(a),0,Mathf.Sin(a));Vector3 pos=Vector3.zero;bool found=false;for(float radius=12;radius<68;radius+=.25f){pos=new Vector3(133,0,130)+dir*radius;float y=terrain.SampleHeight(pos)+terrain.transform.position.y;if(y>6.95f){pos+=dir*(.2f+(float)rng.NextDouble()*4.2f);pos.y=terrain.SampleHeight(pos)+terrain.transform.position.y;if(pos.y<8.6f){found=true;}break;}}if(!found)continue;
var go=(GameObject)PrefabUtility.InstantiatePrefab(sources[(j+k)%5]);go.transform.SetParent(root.transform);go.name=names[(j+k)%5]+" bank patch "+j;go.transform.rotation=Quaternion.Euler(0,(float)rng.NextDouble()*360,0);go.transform.localScale*= (((j+k)%5==2||(j+k)%5==4)?.20f+(float)rng.NextDouble()*.14f:.60f+(float)rng.NextDouble()*.45f)/Bounds(go).size.y;go.transform.position=pos;go.transform.position+=Vector3.up*(pos.y-Bounds(go).min.y-.025f);
foreach(var r in go.GetComponentsInChildren<Renderer>()){r.sharedMaterials=r.sharedMaterials.Select(old=>{if(!mats.TryGetValue(old,out var m)){m=new Material(Shader.Find("Universal Render Pipeline/Lit"));m.name="PondDense_"+old.name;var tex=old.HasProperty("_BaseMap")?old.GetTexture("_BaseMap"):old.GetTexture("_MainTex");m.SetTexture("_BaseMap",tex);m.SetColor("_BaseColor",new Color(.66f,.73f,.59f,1));if(old.HasProperty("_BumpMap"))m.SetTexture("_BumpMap",old.GetTexture("_BumpMap"));m.SetFloat("_Smoothness",.1f);m.SetFloat("_Cull",0);m.SetFloat("_AlphaClip",1);m.SetFloat("_Cutoff",.35f);m.EnableKeyword("_ALPHATEST_ON");m.renderQueue=2450;m.enableInstancing=true;AssetDatabase.DeleteAsset(A+m.name+".mat");AssetDatabase.CreateAsset(m,A+m.name+".mat");mats[old]=m;}return m;}).ToArray();r.shadowCastingMode=ShadowCastingMode.TwoSided;}count++;}}
Aquatic(terrain,root);AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(scene,A+"PondDenseMargins.unity");report.Add(count+" plants in 36 overlapping bank patches; upright height .60–1.05m, rosettes .20–.34m. Source package preserved; shared URP material copies. Ground brightness variation 32% reduced to 6%, random bare soil 22% to 3.5%, dry tint 30% to 8%, broad tint spread reduced. Water, waves, lighting and mature trees unchanged.");File.WriteAllLines(O+"PondDense_Changes.txt",report);Debug.Log("POND FLORA READY "+count);}
static void Aquatic(Terrain terrain,GameObject parent){var rng=new System.Random(942);float R(){return (float)rng.NextDouble();}var reed=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/CityForge/Art/Environment/RollingPondStudy/ReedClump.prefab");var verts=new List<Vector3>();var colors=new List<Color>();var tris=new List<int>();int reeds=0,pads=0;
float[] sectors=Enumerable.Range(0,24).Select(i=>i*6.28318f/24+.07f*Mathf.Sin(i*1.71f)).ToArray();
foreach(float angle in sectors){Vector3 Boundary(float a){var dir=new Vector3(Mathf.Cos(a),0,Mathf.Sin(a));for(float radius=12;radius<68;radius+=.2f){var pos=new Vector3(133,0,130)+dir*radius;pos.y=terrain.SampleHeight(pos)+terrain.transform.position.y;if(pos.y>=6.8f)return pos;}return Vector3.zero;}
for(int k=0;k<28+(int)(angle*11)%38;k++){float a=angle+(R()+R()-1)*.14f;var edge=Boundary(a);var dir=new Vector3(Mathf.Cos(a),0,Mathf.Sin(a));var pos=edge+dir*((R()+R()-1)*3.8f);pos.y=terrain.SampleHeight(pos)+terrain.transform.position.y;if(pos.y<6.15f||pos.y>7.75f)continue;var go=(GameObject)PrefabUtility.InstantiatePrefab(reed);go.transform.SetParent(parent.transform);go.name="Waterline rush clump";go.transform.position=pos;go.transform.rotation=Quaternion.Euler(0,R()*360,0);go.transform.localScale=Vector3.one*(.9f+R()*.8f);reeds++;}
for(int k=0;k<35+(int)(angle*17)%40;k++){float a=angle+(R()+R()-1)*.21f;var edge=Boundary(a);var dir=new Vector3(Mathf.Cos(a),0,Mathf.Sin(a));var pos=edge-dir*(1.5f+R()*6f);float y=terrain.SampleHeight(pos)+terrain.transform.position.y;if(y>6.55f||y<4.8f||R()<.12f)continue;float radius=.23f+R()*.29f,rotation=R()*6.28f;pos.y=6.96f;int start=verts.Count;verts.Add(pos+Vector3.up*.025f);colors.Add(new Color(.32f,.40f,.13f));int n=18;for(int i=0;i<=n;i++){float t=.18f+(6.28318f-.36f)*i/n;float rr=radius*(.92f+.08f*Mathf.Sin(t*3));verts.Add(pos+new Vector3(Mathf.Cos(t+rotation)*rr,0,Mathf.Sin(t+rotation)*rr*.87f));colors.Add(Color.Lerp(new Color(.24f,.33f,.095f),new Color(.43f,.49f,.19f),R()));if(i<n){tris.Add(start);tris.Add(start+i+2);tris.Add(start+i+1);}}pads++;}}
var mesh=new Mesh();mesh.SetVertices(verts);mesh.SetColors(colors);mesh.SetTriangles(tris,0);mesh.RecalculateNormals();mesh.RecalculateBounds();AssetDatabase.DeleteAsset(A+"PondDenseLilyPads.asset");AssetDatabase.CreateAsset(mesh,A+"PondDenseLilyPads.asset");var mat=new Material(Shader.Find("CityForge/Lily Pad Vertex Color"));AssetDatabase.DeleteAsset(A+"PondDenseLilyPads.mat");AssetDatabase.CreateAsset(mat,A+"PondDenseLilyPads.mat");var lily=new GameObject("Shallow water lily colonies");lily.transform.SetParent(parent.transform);lily.AddComponent<MeshFilter>().sharedMesh=mesh;lily.AddComponent<MeshRenderer>().sharedMaterial=mat;File.WriteAllText(O+"PondDense_Aquatic.txt",reeds+" overlapping emergent rush clumps anchored on banks and shallow lake bed; "+pads+" notched lily pads in irregular shallow-water colonies. Procedural prototype pads, existing reed asset, imported Low-Grow Flora bank plants. Water renderer and materials unchanged.");}
static void Capture(){var c=GameObject.Find("Meadow presentation camera").GetComponent<Camera>();c.orthographicSize=40;c.transform.position=new Vector3(133,8,130)-c.transform.forward*110;c.ResetProjectionMatrix();var rt=new RenderTexture(1920,1080,24);rt.Create();var prev=RenderTexture.active;try{RenderPipeline.SubmitRenderRequest(c,new UniversalRenderPipeline.SingleCameraRequest{destination=rt});RenderTexture.active=rt;var t=new Texture2D(1920,1080,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,1920,1080),0,0);t.Apply();File.WriteAllBytes(O+"PondDenseMargins_"+frame+".png",t.EncodeToPNG());UnityEngine.Object.DestroyImmediate(t);}finally{RenderTexture.active=prev;rt.Release();UnityEngine.Object.DestroyImmediate(rt);}}
